using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Entanglement.SymmetricExtensions;

internal sealed class BoseOccupationTwirlDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Entanglement/SymmetricExtensions/BoseOccupationTwirl.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual diagonal-unitary occupation twirl", H("Actual diagonal-unitary occupation twirl"),
        Blocks(
            Paragraph(Text("The twirl is prior work of Gulati-Nechita-Park, Corollary 8.18, and Gulati-Nechita-Pellegrini, Lemma 5.8. The source application from star witnesses is by Haobo Ma and Wenlin Zhang. Matrices use the original computational tensor basis and unnormalized marginals. Averaging can change the witness.")),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-tensorphase"),
                DeclarationHandle.Create(Prefix + "tensorPhase"),
                H("tensorPhase"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The diagonal entry of the repeated local tensor operator is the product of the local entries at every register."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-diagonalaction"),
                DeclarationHandle.Create(Prefix + "diagonalAction"),
                H("diagonalAction"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("This is genuine matrix conjugation by the repeated local diagonal operator, not an abstract occupation projection."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-diagonalaction-possemidef"),
                DeclarationHandle.Create(Prefix + "diagonalAction_posSemidef"),
                H("diagonalAction posSemidef"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every such conjugation preserves positive semidefiniteness."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-cutphase"),
                DeclarationHandle.Create(Prefix + "cutPhase"),
                H("cutPhase"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("At transposed registers the local diagonal entry is complex conjugated; at other registers it is unchanged."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-partialtranspose-diagonalaction"),
                DeclarationHandle.Create(Prefix + "partialTranspose_diagonalAction"),
                H("partialTranspose diagonalAction"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every subset of registers, including the empty and full subsets, the partial transpose of a summand equals conjugation of the same cut of the input by the cut diagonal. This is the actual product-basis transpose."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-diagonalaction-fullyppt"),
                DeclarationHandle.Create(Prefix + "diagonalAction_fullyPPT"),
                H("diagonalAction fullyPPT"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("All nonempty proper PPT inequalities of the input survive each summand."))),
                DescribeRole.Theorem),
            new DocumentBlock.Section(H("Application: unitary conjugation at every cut"), Blocks(
                Paragraph(Text("Let I and L be arbitrary finite types and u : L to Complex satisfy norm(u(a))=1 for every a. For each computational word x : I to L, tensorPhase u x is the product over i of u(x(i)). The norm-product identity gives norm(tensorPhase u x)=1, and Complex.mul_conj' gives tensorPhase u x times its complex conjugate equal to one. Matrix.diagonal_conjTranspose and Matrix.diagonal_mul_diagonal therefore give D D-adjoint=1 for D=diagonal(tensorPhase u). Matrix.mem_unitaryGroup_iff identifies D as an actual unitary matrix.")),
                Paragraph(Text("For every S : Finset I, cutPhase S u x instead conjugates u(x(i)) exactly when i belongs to S. Conjugation preserves the norm, so the same norm-product and Complex.mul_conj' calculation gives norm(cutPhase S u x)=1 and cutPhase S u x times its conjugate equal to one. The same diagonal identities and Matrix.mem_unitaryGroup_iff make diagonal(cutPhase S u) unitary. The existing partialTranspose_diagonalAction identity thus expresses every cut of diagonalAction u E as a unitary conjugation of that same cut of E, for arbitrary E, including empty and full cuts.")),
                Paragraph(Text("These applications of the existing scalar and matrix results include empty index types and require no inverse of E, positivity, nonsingularity or trace normalization. In occupationTwirl the required local norm-one premise is supplied by occupationPhase_norm, so the finite average is an average of actual tensor unitaries. Its exact occupation action is proved by occupation_character_orthogonality and occupationTwirl_apply.")))),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-edgemarginal-diagonalaction"),
                DeclarationHandle.Create(Prefix + "edgeMarginal_diagonalAction"),
                H("edgeMarginal diagonalAction"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For norm-one local phases, every ordered two-register marginal transforms by the corresponding two-site local diagonal conjugation. Complement factors cancel exactly and no dimension factor occurs."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-diagonalaction-bose"),
                DeclarationHandle.Create(Prefix + "diagonalAction_bose"),
                H("diagonalAction bose"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Actual full Bose support is retained, using column symmetry and the canonical symmetric projector."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-diagonalaverage"),
                DeclarationHandle.Create(Prefix + "diagonalAverage"),
                H("diagonalAverage"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The finite sum of actual diagonal conjugations is divided by the cardinality of its indexing type. Trace normalization of the input is never assumed."))),
                DescribeRole.Definition),
            Paragraph(Text("The finite diagonal average preserves positivity term by term; this property is used by the retained occupation twirl application.")),
            Paragraph(Text("Each retained proper PPT cut is transported through the actual diagonal conjugations before averaging.")),
            Paragraph(Text("The full symmetric-projector sandwich is preserved by the diagonal average whenever the input has it.")),
            Paragraph(Text("A prescribed ordered marginal fixed by every local diagonal conjugation is preserved by the finite average, with its original unnormalized trace.")),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-occupationphase"),
                DeclarationHandle.Create(Prefix + "occupationPhase"),
                H("occupationPhase"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Independent local phases are sampled from the (r+1)-st roots of unity. Counts in words of length r are strictly smaller than r+1, so occupation characters cannot alias."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-occupation-character-orthogonality"),
                DeclarationHandle.Create(Prefix + "occupation_character_orthogonality"),
                H("occupation character orthogonality"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The finite character sum is the group cardinality for equal occupations and zero for distinct occupations. Separation is proved from actual occupation counts."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-occupationtwirl"),
                DeclarationHandle.Create(Prefix + "occupationTwirl"),
                H("occupationTwirl"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The explicit finite diagonal-unitary average uses these independent root-of-unity phases on r actual tensor registers."))),
                DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("boseoccupationtwirl-occupationtwirl-apply"),
                DeclarationHandle.Create(Prefix + "occupationTwirl_apply"),
                H("occupationTwirl apply"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("An entry between words with equal occupations is unchanged; an entry between distinct occupations is exactly zero. This finite average has precisely the occupation dephasing action of the diagonal torus."))),
                DescribeRole.Theorem),
            Paragraph(Text("Entrywise occupation dephasing also makes distinct normalized uniform Dicke occupation vectors orthogonal under the averaged matrix.")),
            Paragraph(Text("For a genuine no-PPT Dicke star witness, the explicit occupation twirl is diagonal in the occupation basis, preserves every ordered marginal fixed by the local action, and retains positivity and full Bose support. No inverse, strict positivity, coefficient-sum or trace-one premise is used; zero and singular witnesses remain in scope.")),
            Paragraph(Text("The same finite average transports every fully PPT cut and supplies an existence witness; the averaged matrix need not equal the input.")))));
}
